package io.ivo.mp3;
import io.ivo.container.*;import io.ivo.engine.*;import io.ivo.util.*;import java.nio.file.*;import java.util.*;
public class CorpusTrial {
 static byte[] input,sha;static Path out;static String name;
 static long check(String id,byte[] payload)throws Exception{byte[] packed=IvoContainer.pack(new IvoArchive(EngineId.MP3_V1,input.length,name,sha,payload));Path p=out.resolve(id+".ivo");Files.write(p,packed);IvoArchive a=IvoContainer.unpack(Files.readAllBytes(p));byte[] r=switch(id){case "v1"->Mp3V0Experiment.decodeExactV1(a.payload());case "v3"->ReservoirTrial.decodeV3(a.payload());default->ReservoirTrial.decodeV4(a.payload());};if(!Arrays.equals(input,r)||!Arrays.equals(sha,Hashing.sha256(r)))throw new AssertionError("mismatch "+id);return Files.size(p);}
 public static void main(String[] args)throws Exception{Path p=Path.of(args[0]);out=Path.of(args[1]);Files.createDirectories(out);input=Files.readAllBytes(p);sha=Hashing.sha256(input);name=p.getFileName().toString();long store=IvoContainer.pack(new IvoArchive(EngineId.STORE,input.length,name,sha,input)).length;System.out.println("INPUT "+p+" bytes="+input.length+" sha="+HexFormat.of().formatHex(sha)+" store="+store);try{byte[] v1=Mp3V0Experiment.encodeExactV1(input);long s1=check("v1",v1);byte[] v3=ReservoirTrial.combineV3(input,v1);long s3=check("v3",v3);System.out.println("BASE v1="+s1+" v3="+s3+" exact=true");for(int mode=1;mode<=2;mode++){try{long s=check("v4m"+mode,ReservoirTrial.encodeV4(input,v3,mode));System.out.println("RESULT mode="+mode+" ivo="+s+" delta_vs_v3="+(s-s3)+" exact=true");}catch(IllegalArgumentException e){System.out.println("UNSUPPORTED mode="+mode+" reason="+e.getMessage());}}}catch(Exception e){System.out.println("FAILED "+e);throw e;}}
}
